// Use "take" to view a sample number of records in the table and check the data.
sensors
| take 100

// See how many records are in the table.
sensors
| count

// This query returns the number of ingestions per hour in the given table.
sensors
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)


sensors
| extend metrics_json = todynamic(metrics) // Optionnel : nécessaire uniquement si la colonne est un string
| project 
    eventType,
    sensorId,
    timestamp,
    Temperature = todecimal(metrics_json.temperature_c),
    Pressure = todecimal(metrics_json.pressure_hpa),
    Humidity = todecimal(metrics_json.humidity_pct)
